package biotex;

import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.util.*;
import java.util.List;

public final class Ui {
    public static final Color BG=new Color(0xF5F7FA),WHITE=Color.WHITE,INK=new Color(0x17324D),MUTED=new Color(0x697D91),BLUE=new Color(0x104A80),BLUE_LIGHT=new Color(0xEAF2F9),LIME=new Color(0xB7C800),LINE=new Color(0xE3E9EF),RED=new Color(0xAF3740);
    private Ui(){}
    public static Font font(int size,int weight){return new Font("Segoe UI",weight,size);}
    public static JLabel label(String text,int size,boolean bold){JLabel l=new JLabel(text);l.setFont(font(size,bold?Font.BOLD:Font.PLAIN));l.setForeground(bold?INK:MUTED);return l;}
    public static JPanel card(){JPanel p=new JPanel(new BorderLayout(0,14));p.setBackground(WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(LINE),BorderFactory.createEmptyBorder(20,22,20,22)));return p;}
    public static JPanel row(Component... items){JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT,10,0));p.setOpaque(false);for(Component c:items)p.add(c);return p;}
    public static JButton button(String text,boolean primary,Runnable action){JButton b=new JButton(text);b.setFont(font(12,Font.BOLD));b.setFocusPainted(false);b.setBackground(primary?BLUE:WHITE);b.setForeground(primary?WHITE:INK);b.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(primary?BLUE:LINE),BorderFactory.createEmptyBorder(9,14,9,14)));b.addActionListener(e->action.run());return b;}
    public static JTextField field(String value,int columns){JTextField f=new JTextField(value==null?"":value,columns);f.setFont(font(13,Font.PLAIN));f.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(LINE),BorderFactory.createEmptyBorder(8,10,8,10)));return f;}
    public static JTable table(List<Map<String,Object>> rows,String... keys){String[] headers=Arrays.stream(keys).map(Ui::header).toArray(String[]::new);DefaultTableModel model=new DefaultTableModel(headers,0){public boolean isCellEditable(int r,int c){return false;}};for(var row:rows){Object[] values=new Object[keys.length];for(int i=0;i<keys.length;i++)values[i]=row.get(keys[i]);model.addRow(values);}JTable t=new JTable(model);t.setRowHeight(38);t.setFont(font(12,Font.PLAIN));t.setGridColor(LINE);t.setShowVerticalLines(false);t.setSelectionBackground(BLUE_LIGHT);t.setSelectionForeground(INK);t.getTableHeader().setFont(font(12,Font.BOLD));t.getTableHeader().setBackground(BG);t.getTableHeader().setForeground(INK);t.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);t.setAutoCreateRowSorter(true);DefaultTableCellRenderer right=new DefaultTableCellRenderer();right.setHorizontalAlignment(SwingConstants.RIGHT);for(int i=0;i<keys.length;i++)if(keys[i].matches("(?i).*([qQ]ty|[aA]mount|[pP]rice|[cC]ost|[tT]otal|[rR]ate|[pP]eople|[rR]epeats|[dD]uration|[pP]osition|[cC]m|[gG]sm|[qQ]uantity).*"))t.getColumnModel().getColumn(i).setCellRenderer(right);return t;}
    public static JScrollPane scroll(Component c){JScrollPane s=new JScrollPane(c);s.setBorder(BorderFactory.createEmptyBorder());s.getViewport().setBackground(WHITE);return s;}
    public static String header(String key){return switch(key){case "id"->"ID";case "code"->"Kod";case "name"->"Ad";case "productName"->"Ürün";case "customerName"->"Müşteri";case "category"->"Kategori";case "size"->"Beden";case "sterile"->"Steril";case "active"->"Aktif";case "revision"->"Revizyon";case "unit"->"Birim";case "gsm"->"Gramaj";case "materialName"->"Malzeme";case "supplierName"->"Tedarikçi";case "amount"->"Tutar";case "currency"->"Döviz";case "validFrom"->"Geçerlilik";case "selected"->"Seçili";case "position"->"Sıra";case "quantity"->"Adet";case "widthCm"->"En (cm)";case "heightCm"->"Boy (cm)";case "componentId"->"Bileşen ID";case "materialId"->"Malzeme ID";case "subproductId"->"Alt ürün ID";case "description"->"Açıklama";case "method"->"Yöntem";case "repeats"->"Tekrar";case "manualQty"->"Tüketim";case "wasteRate"->"Fire";case "manualPrice"->"Manuel fiyat";case "sourceCell"->"Kaynak";case "duration"->"Süre";case "timeUnit"->"Süre birimi";case "people"->"Kişi";case "minuteRate"->"Dakika maliyeti";case "scope"->"Kapsam";case "date"->"Tarih";case "tryPerUnit"->"TRY karşılığı";case "status"->"Durum";case "createdAt"->"Tarih";case "unitCost"->"Birim maliyet";case "unitPrice"->"Birim fiyat";case "orderTotal"->"Sipariş toplamı";default->key;};}
}
